                    b.Property<Guid>("BoxId")
                        .HasColumnType("uniqueidentifier");

                    b.Property<decimal>("BoxProgressSnapshot")
                        .HasColumnType("decimal(18,2)");

                    b.Property<DateTime>("CreatedDate")
